const float FOV =  2.;
const int MAX_STEPS = 500;
const float MAX_DIST = 120.0;
const float EPSILON = 0.001;
const float BLUR = .0005;
const float BASE = .18;

float displacement(vec3 p ){

    return 0.018*sin( 13. * PI * p.x);

}


vec2 bottleObj(vec3 p){

    float bottleID = 1.0;
    float capID = 2.0;
    float labelID = 3.0;

    //main body
    vec3 cyl_p = p;
    pR(cyl_p.yz, PI/2.);
    float cylinderDF = sdRoundedCylinder( cyl_p, .58, 0.25, 1.4 );
    vec2 cylinder = vec2(cylinderDF, bottleID);

    //cap
    vec3 cap_p = cyl_p;
    cap_p.y += 2.2;
    float capDF = sdRoundedCylinder( cap_p, .5, 0.2, 0.4 );
    capDF+=displacement(cap_p);
    cap_p.y +=0.22;
    float cap_top = sdRoundedCylinder( cap_p, .49, 0.2, 0.2 );
    capDF = opUnion(capDF, cap_top);
    vec2 cap = vec2(capDF, capID);

    //label
    float labelDF = sdCylinder( cyl_p, 1.18, 0.7 );
    labelDF = opSubtraction(fBox(cyl_p + vec3(1.,0.,0.), vec3(.5, 4.1, 5.1)), labelDF);
    vec2 label = vec2(labelDF, labelID);

    // result
    vec2 bottleObj = opUnionID(cap, cylinder);
    bottleObj = opUnionID(label, bottleObj);

    return bottleObj;

}

vec2 repeated( vec3 p, float s )
{
    vec3 id = round(p/s);
    vec3 r = p - s*round(p/s);

    r = vec3( ((int(id.x)&1)==0) ? -r.x : r.x,
              ((int(id.y)&1)==0) ? r.y : -r.y, 
              ((int(id.z)&1)==0) ? r.z : -r.z
             );          

    pR(r.zx, 3. * iTime);
    pR(r.yz, PI/3.);

    return bottleObj(r);
}

vec2 map(vec3 p){
// this function contains the distance functions of all objects and returns the closest one
// using the union operator

    vec3 p_E = p;

    pR(p_E.yx, 1.5 * iTime);
    pR(p_E.xz, PI/6.);

    // return bottleObj(p_E)
    return repeated(p_E, 25.);

}

vec2 rayMarch(vec3 ro, vec3 rd){
// the rayMarch function returns a 2-dimensiona vector object in order to store
// the distance to the object in the X component, and get the object ID ( it's color) 
// in the Y component
    vec2 hit, object;
    for(int i = 0; i < MAX_STEPS; i++){
        // march the ray p ...
        vec3 p = ro + object.x * rd;
        // and compute distance from the objects
        hit = map(p);
        // update distance from the objects and ID
        object.x += hit.x;
        object.y = hit.y;
        // stop is object is hit ( really small distance ) or ray has travelled to far away
        if(abs(hit.x) < EPSILON || object.x > MAX_DIST) break;
    }
    return object;
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(EPSILON, 0.0);
    vec3 n = vec3(map(p).x) - vec3(map(p - e.xyy).x, map(p - e.yxy).x, map(p - e.yyx).x);
    return normalize(n);
}

vec3 getLight(vec3 p, vec3 rd, vec3 color){
// Lighting model based on the Lambert Law: 
// amount of reflected light is proportional to the scalar product of the vector
// directed to the light source and the normal to the surface
    vec3 lightPos = vec3(10., 0., -30.);
    vec3 L = normalize(lightPos - p); // vector from surface element directed to the light source
    vec3 N = getNormal(p);  

    // return N; //check normals
    // compute the Lambert Law
    vec3 diffuse = color * clamp(dot(L, N), 0.0, 1.0);

    // shadows
    float d = rayMarch(p + N * 0.02, normalize(lightPos)).x; // cast ray from surface point p towards the light and get distance
    // if the distance travelled from p to the ligth is lower that the distance from the point to the light, it means we've hit an object
    // which is obstructing the light, so we cast a shadow for point p
    if (d < length(lightPos - p)) return vec3(0.0);

    return diffuse;
}


vec3 getMaterial(vec3 p, float id) {
// Gives the color based on the ID of the hit object
    vec3 m;
    switch (int(id)) {
        case 1:
        m = vec3(200./255., 87./255., 35./255.); break;
        case 2:
        m = vec3(1.); break;
        case 3:
        m = vec3(.25, .11, .3); break;
    }
    return m;
}

void render(inout vec3 col, in vec2 uv){
    // sets ray origin
    vec3 ro = vec3(0., 4.0, -10. + 10. * sin(iTime));
    // sets ray directionS -> points towards xy plane 
    vec3 rd = normalize(vec3(uv, FOV));

    vec3 bck_col =  vec3(0., 1., 0.);

    vec2 object = rayMarch(ro, rd);

    if(object.x < MAX_DIST * 0.5){
        vec3 p = ro + object.x * rd;
        vec3 material = getMaterial(p, object.y);
        col += getLight(p, rd, material);
        col = smoothstep(BASE-BLUR,BASE+BLUR,col);
        // remove crappy background elements
        if(object.x > 72.){
            col = bck_col;
        }

    }else{
        col = bck_col;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (x,y in (-1,1))
    vec2 uv = (2.0 * fragCoord.xy - iResolution.xy) /iResolution.y;

    vec3 col;
    //AA setting
    int aa_factor = 4;

    // Supersampling - nxn grid within each pixel
    for(int x = 0; x < aa_factor; x++) {
        for(int y = 0; y < aa_factor; y++) {
            // Offset for each sample - shifts within the pixel grid
            vec2 offset = vec2(x, y) * (1. / float(aa_factor)) / iResolution.y;
            // Adjusted UV for current sample
            vec2 sampleUV = uv + offset;
            // Render scene for this sample
            vec3 sampleColor;
            render(sampleColor, sampleUV);
            col += sampleColor;
        }
    }

    // Average the color from the samples
    col /= float(aa_factor * aa_factor);

    // Output to screen
    fragColor = vec4(col,1.0);
}

#define PI 3.14159265359

////////////////////////////////////////////////////////////////
//
//                DOMAIN MANIPULATION OPERATORS
//
////////////////////////////////////////////////////////////////

// Rotate around a coordinate axis (i.e. in a plane perpendicular to that axis) by angle <a>.
// Read like this: R(p.xz, a) rotates "x towards z".
// This is fast if <a> is a compile-time constant and slower (but still practical) if not.
void pR(inout vec2 p, float a) {
	p = cos(a)*p + sin(a)*vec2(p.y, -p.x);
}

// Maximum/minumum elements of a vector
float vmax(vec2 v) {
	return max(v.x, v.y);
}

float vmax(vec3 v) {
	return max(max(v.x, v.y), v.z);
}

float vmax(vec4 v) {
	return max(max(v.x, v.y), max(v.z, v.w));
}

float fPlane(vec3 p, vec3 n, float distanceFromOrigin) {
	return dot(p, n) + distanceFromOrigin;
}

float sdRoundedCylinder( vec3 p, float ra, float rb, float h )
{
  vec2 d = vec2( length(p.xz)-2.0*ra+rb, abs(p.y) - h );
  return min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rb;
}

// Cylinder standing upright on the xz plane
float sdCylinder(vec3 p, float r, float height) {
	float d = length(p.xz) - r;
	d = max(d, abs(p.y) - height);
	return d;
}

float ndot(vec2 a, vec2 b ) { return a.x*b.x - a.y*b.y; }

float fRhombus( vec3 p, float la, float lb, float h, float ra )
{
  p = abs(p);
  vec2 b = vec2(la,lb);
  float f = clamp( (ndot(b,b-2.0*p.xz))/dot(b,b), -1.0, 1.0 );
  vec2 q = vec2(length(p.xz-0.5*b*vec2(1.0-f,1.0+f))*sign(p.x*b.y+p.z*b.x-b.x*b.y)-ra, p.y-h);
  return min(max(q.x,q.y),0.0) + length(max(q,0.0));
}

float fBox(vec3 p, vec3 b) {
	vec3 d = abs(p) - b;
	return length(max(d, vec3(0))) + vmax(min(d, vec3(0)));
}

////////////////////////////////////////////////////////////////
//
//             OBJECT COMBINATION OPERATORS
//
////////////////////////////////////////////////////////////////


float opUnion( float d1, float d2 )
{
    return min(d1,d2);
}

float opSubtraction( float d1, float d2 )
{
    return max(-d1,d2);
}

vec2 opUnionID(vec2 res1, vec2 res2){
// returns the closestbetween 2 objects ( distance and ID ) 
    return (res1.x < res2.x) ? res1 : res2;
}


vec2 opSubtractionID(vec2 res1, vec2 res2) {
    return (res1.x > -res2.x) ? res1 : vec2(-res2.x, res2.y);
}

